import numpy as np
from PIL import Image
from scipy import ndimage
import json, sys, os

tasks = {t['id']: t for t in json.load(open('tasks.json'))}

def interp(p, a, b, va, vb, scale):
    if scale == 'log':
        la, lb = np.log10(va), np.log10(vb)
        return 10 ** (la + (p-a)/(b-a)*(lb-la))
    return va + (p-a)/(b-a)*(vb-va)

def px_to_val(px, py, task):
    x1, v1 = task['x_ticks'][0]['pixel_x'], task['x_ticks'][0]['value']
    x2, v2 = task['x_ticks'][1]['pixel_x'], task['x_ticks'][1]['value']
    y1, w1 = task['y_ticks'][0]['pixel_y'], task['y_ticks'][0]['value']
    y2, w2 = task['y_ticks'][1]['pixel_y'], task['y_ticks'][1]['value']
    return (interp(px, x1, x2, v1, v2, task['x_scale']),
            interp(py, y1, y2, w1, w2, task['y_scale']))

def color_mask(arr, target, tol=40):
    r,g,b = arr[:,:,0].astype(int), arr[:,:,1].astype(int), arr[:,:,2].astype(int)
    return (np.abs(r-target[0])<=tol)&(np.abs(g-target[1])<=tol)&(np.abs(b-target[2])<=tol)

def cluster_pts(mask, min_size=8, max_size=10**9):
    lab, n = ndimage.label(mask)
    pts = []
    for i in range(1, n+1):
        ys, xs = np.where(lab==i)
        if min_size <= len(ys) <= max_size:
            pts.append((float(xs.mean()), float(ys.mean()), int(len(ys))))
    return pts

def extract(fname, target, min_size=8, max_size=10**9, tol=40):
    im = Image.open(f'images/{fname}')
    arr = np.array(im)
    mask = color_mask(arr, target, tol)
    pts = cluster_pts(mask, min_size, max_size)
    task = tasks[fname]
    out = [px_to_val(x,y,task) for x,y,_ in pts]
    return out, len(mask)

if __name__ == '__main__':
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument('fname'); ap.add_argument('r'); ap.add_argument('g'); ap.add_argument('b')
    ap.add_argument('--min', type=int, default=8); ap.add_argument('--max', type=int, default=10**9)
