    return va + (p-a)/(b-a)*(vb-va)

def px_to_val(px, py, task):
    x1, v1 = task['x_ticks'][0]['pixel_x'], task['x_ticks'][0]['value']
    x2, v2 = task['x_ticks'][1]['pixel_x'], task['x_ticks'][1]['value']
    y1, w1 = task['y_ticks'][0]['pixel_y'], task['y_ticks'][0]['value']
    y2, w2 = task['y_ticks'][1]['pixel_y'], task['y_ticks'][1]['value']
    return (interp(px, x1, x2, v1, v2, task['x_scale']),
            interp(py, y1, y2, w1, w2, task['y_scale']))

def get_mask(fname, spec, tol):
    arr = np.array(Image.open(f'images/{fname}')).astype(int)
    if spec[0] == 'exact':
        r,g,b = spec[1]
        return (np.abs(arr[:,:,0]-r)<=tol)&(np.abs(arr[:,:,1]-g)<=tol)&(np.abs(arr[:,:,2]-b)<=tol)
    if spec[0] == 'cond':
        return eval(spec[1], {'arr': arr, 'np': np})
    raise ValueError

def clusters(mask, erode_n=0, min_size=4, max_size=10**9, exclude=None):
    m = mask
    if erode_n:
        m = ndimage.binary_erosion(m, iterations=erode_n)
    lab, n = ndimage.label(m)
    pts = []
    for i in range(1, n+1):
        ys, xs = np.where(lab==i)
        if min_size <= len(ys) <= max_size:
            x, y = xs.mean(), ys.mean()
            if exclude and (exclude[0] <= x <= exclude[2]) and (exclude[1] <= y <= exclude[3]):
                continue
            pts.append((float(x), float(y), int(len(ys))))
    return pts

def run(fname, spec, tol=40, erode_n=0, min_size=4, max_size=10**9, exclude=None):
