for i in range(1, n+1):
    h = (lab == i)
    ar = h.sum()
    if ar < 3: continue
    dt = ndimage.distance_transform_edt(h)
    comps, kc = ndimage.label(dt >= 1.2)
    if kc == 0:
        ys, xs = np.where(h)
        main.append((float(xs.mean()), float(ys.mean()), True))
    else:
        for c in range(1, kc+1):
            ys, xs = np.where(comps == c)
            main.append((float(xs.mean()), float(ys.mean()), False))

