    gaps = [(round(xs[i],1), round(xs[i+1],1), round(xs[i+1]-xs[i],1)) for i in range(len(xs)-1) if xs[i+1]-xs[i] > 8]
    print(f'"'{k}: {len(pts)} pts, range {xs[0]:.1f}-{xs[-1]:.1f}, gaps>8K: {gaps}')

json.dump({k:[(round(x,2), round(y,2)) for (x,y) in final[k]] for k in HUE}, open('/tmp/f91f.json','w'), indent=1)

im = Image.open('../images/fig_091.png').convert('RGB')
from PIL import ImageDraw
d = ImageDraw.Draw(im)
colors = {'black':'red','magenta':'blue','cyan':'orange','green':'yellow'}
for k in HUE:
